package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var outputs []string

	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			break
		}
		cmd := strings.TrimSpace(line)
		if cmd == "" {
			continue
		} else if cmd == "builtin_command" {
			outputs = append(outputs, "internal_handled")
		} else if cmd == "external_command" {
			outputs = append(outputs, "external_executed")
		}
	}

	if len(outputs) == 2 && outputs[0] == "internal_handled" && outputs[1] == "external_executed" {
		fmt.Print("oracle_verified")
	} else if len(outputs) > 0 {
		fmt.Print(strings.Join(outputs, "\n"))
	}
}
